insert into i18n_bundles (locale, code, value) values ('ar', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].intro', 'عَنْ أَبِي عُبَيْدٍ، قَالَ:');
insert into i18n_bundles (locale, code, value) values ('ar', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].quote', 'شَهِدْتُ الْعِيدَ مَعَ عُمَرَ فَبَدَأَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ ثُمَّ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ صِيَامِ هَذَيْنِ الْيَوْمَيْنِ، أَمَّا يَوْمُ الْأَضْحَى فَتَأْكُلُونَ مِنْ لَحْمِ نُسُكِكُمْ، وَأَمَّا يَوْمُ الْفِطْرِ فَفِطْرُكُمْ مِنْ صِيَامِكُمْ.');
