insert into i18n_bundles (locale, code, value) values ('ar', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].intro', 'عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:');
insert into i18n_bundles (locale, code, value) values ('ar', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].quote', 'نَهَى عَنْ صِيَامِ يَوْمَيْنِ: يَوْمِ الْأَضْحَى وَيَوْمِ الْفِطْرِ.');
