insert into i18n_bundles (locale, code, value) values ('ar', 'fasting.reason-groups.voluntary.reasons[2].cites[0].intro', 'عَنْ بَعْضِ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ:');
insert into i18n_bundles (locale, code, value) values ('ar', 'fasting.reason-groups.voluntary.reasons[2].cites[0].quote', 'كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُومُ تِسْعَ ذِي الْحِجَّةِ، وَيَوْمَ عَاشُورَاءَ، وَثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ.');
