insert into i18n_bundles (locale, code, value) values ('ar', 'fasting.reason-groups.voluntary.reasons[3].cites[1].intro', 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:');
insert into i18n_bundles (locale, code, value) values ('ar', 'fasting.reason-groups.voluntary.reasons[3].cites[1].quote', 'إِنَّ بِحَسْبِكَ أَنْ تَصُومَ كُلَّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ، فَإِنَّ لَكَ بِكُلِّ حَسَنَةٍ عَشْرَ أَمْثَالِهَا، فَإِنَّ ذَلِكَ صِيَامُ الدَّهْرِ كُلِّهِ.');
