insert into i18n_bundles (locale, code, value) values ('ar', 'fasting.reason-groups.voluntary.reasons[3].cites[2].quote', 'ثَلَاثٌ مِنْ كُلِّ شَهْرٍ، وَرَمَضَانُ إِلَى رَمَضَانَ، فَهَذَا صِيَامُ الدَّهْرِ كُلِّهِ.');
